})().catch(error=>{console.error(error);process.exitCode=1});
"""


def enum(value):
    return str(value[":db/ident"] if isinstance(value, dict) else value).split("/")[-1]


def answer_id(value):
    if isinstance(value, dict):
        return str(value[":answer/id"])
    if isinstance(value, (list, tuple)) and len(value) == 2 and value[0] == ":answer/id":
        return str(value[1])
    return str(value)


def preview(record, index):
    question = record.get("question", record)
    fields = []
    for number, field in enumerate(question[":question/answer-fields"]):
        choices = [{"id": str(answer[":answer/id"]), "type": enum(answer[":answer/type"]),
                    "value": answer[":answer/value"], "feedback": answer.get(":answer/feedback", "")}
                   for answer in field[":answer-field/choices"]]
        correct_id = answer_id(field[":answer-field/correct"])
        correct = next(answer for answer in choices if answer["id"] == correct_id)
        kind = enum(field[":answer-field/type"])
        fields.append({"id": field.get(":answer-field/id", number), "key": field[":answer-field/key"],
                       "type": kind, "answerType": correct["type"], "choices": choices,
                       "correctAnswer": correct, "response": {"value": correct["value"], "choiceId": correct_id}})
    step = {"kind": "question", "contentId": index + 1, "status": "correct", "problem": question[":question/problem"],
            "solution": question.get(":question/worked-solution", ""), "fields": fields}
    return {"activityId": str(index), "title": "Generator review", "type": "lesson", "steps": [step],
            "courseId": "review", "learner": {"id": 1, "name": "Offline review"}}


def resolve_node(playwright, node=None, environment=None):
    """Prefer Playwright's installed runtime over an incompatible system Node."""
    environment = os.environ if environment is None else environment
    explicit = node or environment.get('COURSE_ACADEMY_NODE_EXECUTABLE')
    candidates = [explicit] if explicit else [
        Path(playwright).parent.parent / 'bin/node',
        Path.home() / '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node',
        shutil.which('node', path=environment.get('PATH')),
    ]
    checked, failures = set(), []
    for candidate in candidates:
        if not candidate:
            continue
        executable = shutil.which(str(candidate), path=environment.get('PATH'))
        if not executable or executable in checked:
            continue
        checked.add(executable)
        try:
            result = subprocess.run([executable, '--version'], capture_output=True,
                                    text=True, check=True, timeout=5)
            version = re.fullmatch(r'v(\d+)\.\d+\.\d+\s*', result.stdout)
            if version and int(version[1]) >= 20:
                return executable
            failures.append(f'{executable}: {result.stdout.strip()}')
        except (OSError, subprocess.SubprocessError) as error:
            failures.append(f'{executable}: {error}')
    raise RuntimeError('Playwright requires Node >=20. Set --node or '
                       'COURSE_ACADEMY_NODE_EXECUTABLE to an installed compatible runtime. '
                       + '; '.join(failures))


def render(records, output, asset_roots, browser=None, playwright=None, node=None):
    output = Path(output).resolve()
    output.mkdir(parents=True, exist_ok=True)
    ui = REPO / "ui"
    roots = [Path(root).resolve() for root in asset_roots]
    browser = browser or next(iter(sorted(Path.home().glob(".cache/ms-playwright/chromium_headless_shell-*/chrome-headless-shell-linux64/chrome-headless-shell"), reverse=True)), None)
    playwright = playwright or os.environ.get("COURSE_ACADEMY_PLAYWRIGHT_MODULE") or Path.home() / ".cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright"
    if not browser or not Path(browser).is_file() or not Path(playwright).exists():
        raise RuntimeError("Installed Node Playwright, node, and Chromium headless shell are required; use --browser/--playwright for existing alternatives")
    node = resolve_node(playwright, node)

    class Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            parsed = urlparse(self.path)
            path = unquote(parsed.path)
            if path == "/api/developer-mode":
                data, kind = json.dumps({"enabled": True}).encode(), "application/json"
            elif path == "/api/preview":
                try:
                    index = int(parse_qs(parsed.query)["activityId"][0])
                    data, kind = json.dumps(preview(records[index], index)).encode(), "application/json"
                except (IndexError, KeyError, ValueError):
                    self.send_error(400); return
            else:
                file = None
                if path == "/learn":
                    file = ui / "Learning.html"
                elif path.startswith("/ui/"):
                    candidate = (ui / path[4:]).resolve()
                    if candidate.is_relative_to(ui):
                        file = candidate
                elif path == "/api/asset":
                    relative = Path(parse_qs(parsed.query).get("path", [""])[0])
                    for root in roots:
                        candidate = (root / relative).resolve()
                        if candidate.is_relative_to(root) and candidate.is_file():
                            file = candidate; break
                if file is None or not file.is_file():
                    self.send_error(404); return
                data, kind = file.read_bytes(), mimetypes.guess_type(file)[0] or "application/octet-stream"
            self.send_response(200)
            self.send_header("Content-Type", kind)
            self.end_headers()
            self.wfile.write(data)

        def do_POST(self):
            self.send_error(405, "Review fixture has no mutation routes")

        def log_message(self, *_args):
            pass
# Math content format: course-academy-tex-v1

Capture, stored lesson content, and generators share this format. Its implementation
is `scripts/question_capture/math_format.py`; the player renders it through the
existing Markdown math protection and MathJax configuration.

| Content | Stored form |
| --- | --- |
| Inline math in prose | `$x+1$` |
| Display math in prose | `$$` on its own line, TeX, then `$$` on its own line |
| Math answer (`:answer.type/math`) | Bare TeX, without dollar delimiters; the UI supplies them once |
| Ordinary square-bracket matrix or column vector | `\begin{bmatrix}1 & 3 \\ 2 & 0\end{bmatrix}` |
| Augmented matrix | `\left[\begin{array}{cc|c}1 & 3 & 7 \\ 2 & 0 & 4\end{array}\right]` |
| System with a left brace | `\left\{\begin{aligned}x+3y &=7 \\ 2x &=4\end{aligned}\right.` |
| Equations without a brace | `\begin{aligned}x+3y &=7 \\ 2x &=4\end{aligned}` |

Use `&` between matrix columns and **two literal backslashes** between rows.
JSON serialization escapes those backslashes; deserialize exactly once. Use `&=`
for equation alignment. An annotation belongs in a separate alignment pair (`&&`).
A braced system ends with the invisible delimiter `\right.`. A literal `{` starts
a TeX group; `\{` alone makes a fixed-size glyph and is not the system convention.
Piecewise functions retain `cases` when rows have values and conditions.
Parenthesized matrices and determinants retain `pmatrix` and `vmatrix`.

An augmentation bar is mathematical content. Choose it explicitly from the matrix's
role or source MathML column rules. Never infer it from the lesson title or from
an occurrence of “augmented” elsewhere in a question. A coefficient matrix has no
augmentation bar, even in a worked solution that also shows an augmented matrix.

## Producer integration

Use `matrix_tex(rows, augmented=...)` and `system_tex(equations)` for new content.
Use `normalize_prose` for prose and `normalize_tex` for math answers **before**
calculating content IDs. Decorate a generator's public `generate` function with
`checked_math_content` so invalid or noncanonical content fails before saving.
The capture transaction builder calls `normalize_capture_question` at its save
boundary, after DOM extraction and before transaction construction.

Normalization repairs supported legacy wrappers without guessing missing math.
Validation rejects unpaired dollar delimiters, unbalanced groups/environments,
legacy layout macros, and ragged matrix rows. Unknown images remain image assets;
only recoverable mathematical source is converted to TeX. Keep immutable source
captures for fidelity checks and compare mathematics separately from typography.

Run `python3 -m unittest discover -s scripts/question_capture -p test_math_format.py`.
For lesson migrations, also render the complete affected content with the player's
actual Markdown, sanitization, and MathJax pipeline. A lack of MathJax errors alone
is insufficient: check for exposed delimiters, row counts, scalable braces, and
aligned equals signs.

